/*-- Reset CSS --*/
.CSS_LIGHTBOX{z-index:999999!important}.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{opacity:0}a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{
    padding:0;
    border:0;
    outline:0;
    vertical-align:baseline;
    background:0 0;
    text-decoration:none
}
#google_translate_element { clear: both; }.thread-expanded .thread-count a { display: none; }.comments .continue { display: none!important; } 
form,textarea,input,button{
    -webkit-appearance:none;
    -moz-appearance:none;
    appearance:none;
    border-radius:0
}
dl,ul{
    list-style-position:inside;
    font-weight:400;
    list-style:none
}
ul li{
    list-style:none
}
caption,th{
    text-align:center
}
img{
    border:none;
    position:relative
}
a,a:visited{
    text-decoration:none
}
.clearfix{
    clear:both
}
.section,.widget,.widget ul{
    margin:0;
    padding:0
}
a{
    color:$(body.link.color)
}
/* visited link */
.post-body a:visited {
color: white;
}

/* selected link */
a:active {
color: blue;
}
a img{
    border:0
}
abbr{
    text-decoration:none
}
.CSS_LIGHTBOX{
    z-index:999999!important
}
.separator a{
    clear:none!important;
    float:none!important;
    margin-left:0!important;
    margin-right:0!important
}
#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{
    display:none!important
}
.center{
    display:table;
    margin:0 auto;
    position:relative
}
.widget > h2,.widget > h3{
    display:none
}
/*-- Body Content CSS --*/
body{
    background:$(body.background);
    background: #FFFFFF;
    background: #e2e2e2;
    background: #e2e2e2;
    background: #e2e2e2;
    font-family:'Fira Sans',Arial,sans-serif;
    font-size:14px;
    font-weight:400;
    color:#000000;
    word-wrap:break-word;
    margin:0;
    padding:0
}
h1,h2,h3,h4,h5,h6{

}
#outer-wrapper{
}
.row{
    width:900px
}
#content-wrapper{
    background:#ffffff;
    overflow: hidden;
    margin:40px auto 0;
    border-top-left-radius: 7px;
    border-top-right-radius: 7px;
}
#content-wrapper > .container{
    margin:0
}
.item #content-wrapper > .container {
    padding: 15px 15px 0 15px;
    box-sizing: border-box;
}
/* 사이드바 컨테이너 */
#left-side-container {
display: none;
}

#right-side-container {
position: absolute;
top: 100px;
width: 230px;
z-index: 999;
transition: all 0.3s ease;
}

/* 글(post) 페이지에서만 표시 */
/* 글(post) 페이지에서만 표시 -> 전체 페이지 표시로 변경 */
#left-side-container {
display: block;
position: fixed;
top: 100px;
left: calc(50% - 700px);
width: 230px;
z-index: 999;
transition: all 0.3s ease;
}

/* 오른쪽 사이드바 위치 설정 - 기본값 */
#right-side-container {
right: max(20px, min(270px, (100vw - 900px) / 2 - 20px));
}

/* 왼쪽 오른쪽 카드 스타일 */
.right-square-box-card,
.left-square-box-card {
width: 230px;
background: white;
border-radius: 3px;
overflow: hidden;
box-shadow: 2px 2px 10px rgba(0,0,0,0.2);
position: relative;
font-family: sans-serif;
display: flex;
flex-direction: column;
justify-content: space-between;
transition: all 0.3s ease;
}

.right-square-box-card {
height: 300px;
}

/* 이미지 */
.card-image {
position: relative;
width: 100%;
height: 200px;
overflow: hidden;
}

.card-image img {
width: 100%;
height: 100%;
object-fit: cover;
}

/* 이미지 위 텍스트 오버레이 */
.card-text-overlay {
position: absolute;
bottom: 0;
left: 0;
color: white;
width: 100%;
padding: 10px;
background: linear-gradient(to top, rgba(0,0,0,0.6), transparent);
font-size: 13px;
box-sizing: border-box;
}

/* 버튼 영역 */
.card-button {
display: block;
background: #3a2b9d;
color: white;
text-align: center;
padding: 14px 0;
font-size: 15px;
text-decoration: none;
font-weight: bold;
height: 50px;
line-height: 30px;
box-sizing: border-box;
}

/* 닫기 버튼 */
.close-btn {
position: absolute;
top: 6px;
right: 8px;
background: transparent;
border: none;
font-size: 18px;
color: rgb(208, 48, 48);
cursor: pointer;
}

/* 반응형 디자인 */
/* 큰 데스크톱 화면 (1400px 이상) */
@media (min-width: 1401px) {
#right-side-container {
    right: max(30px, (100vw - 1200px) / 2 - 20px);
    width: 150px;
}

.right-square-box-card {
    width: 230px;
    height: 230px;
}

.card-image {
    height: 250px;
}
}

/* 데스크톱 화면 (1200px - 1400px) */
@media (min-width: 1201px) and (max-width: 1400px) {
#right-side-container {
    left: calc(50% + 470px) !important;
    right: auto !important;
    width: 230px;
}

.right-square-box-card {
    width: 230px;
    height: 230px;
}

.card-image {
    height: 200px;
}
}

/* 작은 데스크톱 화면 (992px - 1200px) */
@media (min-width: 992px) and (max-width: 1200px) {
#right-side-container {
    left: calc(50% + 470px) !important;
    right: auto !important;
    width: 230px;
}

.right-square-box-card {
    width: 230px;
    height: 230px;
}

.card-image {
    height: 230px;
}
}

/* 태블릿 화면 (768px - 991px) */
@media (min-width: 768px) and (max-width: 991px) {
#right-side-container {
    right: 15px;
    width: 220px;
}

.right-square-box-card {
    width: 220px;
    height: 220px;
}

.card-image {
    height: 240px;
}

.card-text-overlay {
    font-size: 12px;
    padding: 8px;
}

.card-button {
    font-size: 14px;
    height: 46px;
    line-height: 26px;
}
}

/* 작은 화면 (576px - 767px) */
@media (min-width: 576px) and (max-width: 767px) {
#right-side-container {
    position: static;
    width: 100%;
    max-width: 100%;
}

.right-square-box-card {
    width: 100%;
}
}

/* 모바일 화면 (575px 이하) */
@media (max-width: 575px) {
#right-side-container {
    position: static;
    width: 100%;
    margin: 20px auto;
    padding: 0 15px;
    box-sizing: border-box;
}

.right-square-box-card {
    width: 100%;
    height: auto;
    min-height: 200px;
}

.card-image {
    height: 200px;
}
}

/* 작은 화면에서는 사이드바를 콘텐츠 아래에 표시 */
@media (max-width: 1100px) {
#left-side-container {
    display: none !important;
}

#right-side-container {
    display: none !important;
}

.right-square-box-card {
    margin: 0 auto;
}
}
/* 반응형 디자인 - 왼쪽 사이드바 */
/* 큰 데스크톱 화면 (1400px 이상) */
@media (min-width: 1401px) {
#left-side-container {
    left: calc(50% - 620px);
    width: 150px;
}

.left-square-box-card {
    width: 230px;
    height: 250px;
}
}

/* 데스크톱 화면 (1200px - 1400px) */
@media (min-width: 1201px) and (max-width: 1400px) {
#left-side-container {
    left: calc(50% - 700px) !important;
    width: 230px;
}

.left-square-box-card {
    width: 230px;
    height: 250px;
}
}

/* 작은 데스크톱 화면 (992px - 1200px) */
@media (min-width: 992px) and (max-width: 1200px) {
#left-side-container {
    left: calc(50% - 700px) !important;
    width: 230px;
}

.left-square-box-card {
    width: 230px;
    height: 250px;
}
}

/* 태블릿 화면 (768px - 991px) */
@media (min-width: 768px) and (max-width: 991px) {
.item #left-side-container {
    left: 90px;
    width: 220px;
}

.left-square-box-card {
    width: 220px;
    height: 290px;
}
}

/* 작은 화면에서는 사이드바를 콘텐츠 아래에 표시 */
@media (max-width: 1100px) {
#left-side-container {
    display: none !important;
}
}
#main-wrapper{
    width: 100% !important;
    margin: auto;
    position: relative;
    z-index: 2;
}
.post-image-wrap {
    position: relative !important;
    display: block !important;
    width: 100% !important;
    height: 0 !important;
    padding-bottom: 100% !important; /* 1:1 정사각형 비율 강제 */
    overflow: hidden !important;
    background-color: rgba(155,155,155,0.07) !important;
    border-radius: 8px !important;
}

.post-image-link {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    display: block !important;
    background-color: rgba(155,155,155,0.07) !important;
    color: transparent !important;
}

.post-thumb {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    
    object-fit: cover !important;
    object-position: center !important;
    
    opacity: 1 !important;
    visibility: visible !important;
    display: block !important;
    
    background-color: #f5f5f5 !important;
    z-index: 1 !important;
    transition: transform .35s ease !important;
}

.post-thumb.lazy-yard {
    opacity: 1 !important;
}

.post-image-link:hover .post-thumb,
.post-image-wrap:hover .post-image-link .post-thumb,
.hot-item-inner:hover .post-image-link .post-thumb {
transform: scale(1.05) !important;
}

.post-image-link:hover .post-thumb,
.post-image-wrap:hover .post-image-link .post-thumb {
    opacity: 0.9 !important;
}

.item-post .post-body img {
    max-width: 100% !important;
    opacity: 1 !important;
    transition: opacity .17s ease, transform .35s ease !important;
}

.item-post .post-body img.lazy-yard {
    opacity: 1 !important;
}

.index-post .post-thumb,
.blog-posts .post-thumb,
.hot-posts .post-thumb {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    opacity: 1 !important;
}

/* 데스크톱은 기존 방식 유지 */
@media (min-width: 769px) {
    .post-image-wrap {
        position: relative !important;
        display: block !important;
        width: 100% !important;
        height: 0 !important;
        padding-bottom: 100% !important; /* 정사각형 */
        overflow: hidden !important;
        background-color: rgba(155,155,155,0.07) !important;
        border-radius: 8px !important;
    }
}

/* 모바일은 고정 높이 방식 */
@media (max-width: 768px) {
    .post-image-wrap {
        position: relative !important;
        display: block !important;
        width: 100% !important;
        height: 200px !important; /* 고정 높이로 변경 */
        padding-bottom: 0 !important; /* 패딩 제거 */
        overflow: hidden !important;
        background-color: rgba(155,155,155,0.07) !important;
        border-radius: 6px !important;
        margin-bottom: 0 !important; /* 여백 제거 */
    }
    
    .post-image-link {
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        display: block !important;
        margin: 0 !important; /* 여백 제거 */
        padding: 0 !important; /* 패딩 제거 */
    }
    
    .post-thumb {
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        height: 100% !important;
        object-fit: cover !important;
        object-position: center !important;
        opacity: 1 !important;
        visibility: visible !important;
        display: block !important;
        margin: 0 !important; /* 여백 제거 */
        padding: 0 !important; /* 패딩 제거 */
    }
    
    /* 카드 컨테이너 여백도 조정 */
    .index-post, .post-outer {
        margin-bottom: 15px !important; /* 카드 간 간격 줄이기 */
    }
    
    /* 제목과 썸네일 사이 간격 제거 */
    .post-image-wrap + * {
        margin-top: 10px !important;
    }
}

/* 더 작은 모바일 화면 */
@media (max-width: 480px) {
    .post-image-wrap {
        height: 180px !important; /* 더 작은 화면에서는 높이 줄이기 */
        border-radius: 4px !important;
    }
}

/* 추가: 모든 여백 요소 강제 제거 */
@media (max-width: 768px) {
    .post-image-wrap::before,
    .post-image-wrap::after,
    .post-image-link::before,
    .post-image-link::after {
        display: none !important;
        content: none !important;
    }
    
    /* 혹시 있을 수 있는 추가 여백들 */
    .post-image-wrap {
        box-sizing: border-box !important;
        vertical-align: top !important;
        line-height: 0 !important;
    }
}
.post-title a{
    display:block
}
.social a:before{
    display:inline-block;
    font-family:'Font Awesome 5 Brands';
    font-style:normal;
    font-weight:400
}
.social .facebook a:before{
    content:"\f09a"
}
.social .twitter a:before{
    content:"\f099"
}
.social .gplus a:before{
    content:"\f0d5"
}
.social .rss a:before{
    content:"\f09e";
font-family:'Font Awesome 5 Free';
font-weight:900
}
.social .youtube a:before{
    content:"\f167"
}
.social .skype a:before{
    content:"\f17e"
}
.social .stumbleupon a:before{
    content:"\f1a4"
}
.social .tumblr a:before{
    content:"\f173"
}
.social .vk a:before{
    content:"\f189"
