#header-wrap{
    position:relative;
    width:100%;
    height:70px;
    background-color:#000;
    -webkit-box-shadow: 0 4px 30px #00000012;
box-shadow: 0 4px 30px #00000012;
    z-index:1010;
}
#header-wrap .container{
    position:relative;
    margin:0 auto
}
.header-logo{
    float:left;
    margin:0 20px 0 0
}
.main-logo{
    position:relative;
    float:left;
    width:auto;
    max-width:250px;
    max-height:52px;
    margin:0;
    padding:9px 0
}
.main-logo .header-image-wrapper{
    display:block
}
.main-logo img{
    max-width:100%;
    max-height:52px;
    margin:0
}
.main-logo h1, .main-logo h1 a{
    color:#FFFFFF;
    font-size:25px;
    line-height:52px;
    margin:0
}
.main-logo p{
    font-size:12px;
    margin:5px 0 0;
display:none;
}
.header-menu{
    float:left;
}
#main-menu .widget,#main-menu .widget > h3{
    display:none
}
#main-menu .show-menu{
    display:block
}
#main-menu{
    position:static;
    height:70px;
    z-index:15
}
#main-menu ul > li{
    float:left;
    position:relative;
    margin:0;
    padding:0;
    transition:background .17s ease
}
#main-menu ul > li > a{
    position:relative;
    color:$(menu.color);
    font-size:14px;
    font-weight:500;
    line-height:70px;
    display:inline-block;
    text-decoration:none;
    margin:0;
    padding:0 15px;
    transition:color .17s ease
}
#main-menu ul#main-menu-nav > li:hover{
    background-color:rgba(255,255,255,0.05)
}
#main-menu ul#main-menu-nav > li:hover > a{
    color:$(menu.color)
}
#main-menu ul > li > ul{
    position:absolute;
    float:left;
    left:0;
    top:70px;
    width:180px;
    background-color:$(submenu.bg);
    z-index:99999;
    margin-top:0;
    padding:0;
    border:1px solid rgba(155,155,155,0.15);
    box-shadow:0 2px 2px rgba(0,0,0,0.2);
    visibility:hidden;
    opacity:0
}
#main-menu ul > li > ul > li > ul{
    position:absolute;
    float:left;
    top:0;
    left:100%;
    margin:-1px 0 0
}
#main-menu ul > li > ul > li{
    display:block;
    float:none;
    position:relative;
    background-color:rgba(255,255,255,0.03);
    border-bottom:1px solid rgba(155,155,155,0.15);
    transition:background .17s ease
}
#main-menu ul > li > ul > li a{
    display:block;
    height:36px;
    font-size:13px;
    color:$(submenu.color);
    font-weight:500;
    line-height:36px;
    box-sizing:border-box;
    margin:0;
    padding:0 15px;
    transition:color .17s ease
}
#main-menu ul > li > ul > li:last-child{
    border-bottom:0
}
#main-menu ul > li.has-sub > a:after{
    content:'\f078';
    float:right;
font-family:'Font Awesome 5 Free';
    font-size:12px;
    font-weight:900;
    margin:0 0 0 6px
}
#main-menu ul > li > ul > li.has-sub > a:after{
    content:'\f054';
    float:right;
    margin:0
}
#main-menu ul > li > ul > li a:hover{
    color:$(main.color)
}
#main-menu ul > li:hover > ul,#main-menu ul > li > ul > li:hover > ul{
    visibility:visible;
    opacity:1
}
#main-menu ul ul{
    transition:all .17s ease
}
#main-menu .mega-menu{
    position:static!important
}
#main-menu .mega-menu > ul{
    width:100%;
    box-sizing:border-box;
    padding:20px 10px
}
#main-menu .mega-menu > ul.mega-menu-inner{
    overflow:hidden
}
#main-menu ul > li:hover > ul,#main-menu ul > li > ul > li:hover > ul{
    visibility:visible;
    opacity:1
}
#main-menu ul ul{
    transition:all .25s ease
}
.mega-menu-inner .mega-item{
    float:left;
    width:20%;
    box-sizing:border-box;
    padding:0 10px
}
.mega-menu-inner .mega-content{
    position:relative;
    width:100%;
    overflow:hidden;
    padding:0
}
.mega-content .post-image-wrap{
    width:100%;
    height:120px
}
.mega-content .post-image-link{
    width:100%;
    height:100%;
    z-index:1;
    display:block;
    position:relative;
    overflow:hidden;
    padding:0
}
.mega-content .post-title{
    position:relative;
    font-size:13px;
    font-weight:600;
    line-height:1.5em;
    margin:7px 0 5px;
    padding:0
}
.mega-content .post-title a{
    display:block;
    color:$(posts.title.color);
    transition:color .17s
}
.mega-content .post-title a:hover{
    color:$(main.color)
}
.mega-content .post-meta{
    font-size:11px
}
.no-posts{
    float:left;
    width:100%;
    height:100px;
    line-height:100px;
    text-align:center
}
.mega-menu .no-posts{
    line-height:60px;
    color:$(title.color)
}
.show-search,.hide-search{
    position:absolute;
    top:0;
    right:0;
    display:block;
    width:58px;
    height:70px;
    background-color:rgba(255,255,255,0.05);
    line-height:70px;
    z-index:20;
    color:$(menu.color);
    font-size:16px;
    font-weight:400;
    text-align:center;
    cursor:pointer;
    transition:color .17s ease
}
.show-search:hover,.hide-search:hover{
    color:$(menu.color)
}
.show-search:before{
    content:"\f002";
    font-family:'Font Awesome 5 Free';
    font-weight: 900;
}
.hide-search:before{
    content:"\f00d";
    font-family:'Font Awesome 5 Free';
    font-weight: 900;
}
#nav-search{
    display:none;
    position:absolute;
    left:0;
    top:0;
    width:100%;
    height:70px;
    z-index:99;
    background-color:$(header.bg);
    box-sizing:border-box;
    padding:0
}
#nav-search .search-form{
    width:100%;
    height:70px;
    background-color:rgba(0,0,0,0);
    line-height:70px;
    overflow:hidden;
    padding:0
}
#nav-search .search-input{
    width:100%;
    height:70px;
    font-family:inherit;
    color:$(menu.color);
    margin:0;
    padding:0 58px 0 10px;
    background-color:#3152b7;
    font-size:13px;
    font-weight:400;
    box-sizing:border-box;
    border:0
}
#nav-search .search-input:focus{
    color:$(menu.color);
    outline:none
}
.mobile-menu-toggle{
    display:none;
    position:absolute;
    top:0;
    left:0;
    width:58px;
    height:70px;
    line-height:70px;
    background-color:rgba(255,255,255,0.05);
    z-index:20;
    color:$(menu.color);
    font-size:17px;
    font-weight:400;
    text-align:center;
    cursor:pointer;
    transition:color .17s ease
}
.mobile-menu-toggle:hover{
    color:$(menu.color)
}
.mobile-menu-toggle:before{
    content:"\f0c9";
font-family:'Font Awesome 5 Free';
font-weight:900;
}
.nav-active .mobile-menu-toggle:before{
    content:"\f00d";
font-family:'Font Awesome 5 Free';
font-weight:900;
}
.overlay{
    display:none;
    position:fixed;
    top:0;
    left:0;
    right:0;
    bottom:0;
    z-index:990;
    background:rgba(255,255,255,0.8)
}
.mobile-menu-wrap{
    display:none;
    position:absolute;
    top:70px;
    left:0;
    width:100%;
    background-color:$(submenu.bg);
    box-sizing:border-box;
    visibility:hidden;
    z-index:1000;
    opacity:0;
    transition:all .17s ease
}
.nav-active .mobile-menu-wrap{
    visibility:visible;
    opacity:1
}
.mobile-menu{
    position:relative;
    overflow:hidden;
    padding:20px;
    border-top:1px solid rgba(255,255,255,0.03)
}
.mobile-menu > ul{
    margin:0
}
.mobile-menu .m-sub{
    display:none;
    padding:0
}
.mobile-menu ul li{
    position:relative;
    display:block;
    overflow:hidden;
    float:left;
    width:100%;
    font-size:14px;
    line-height:38px
}
.mobile-menu > ul > li{
    font-weight:500;
}
.mobile-menu > ul li ul{
    overflow:hidden
}
.mobile-menu ul li a{
    color:$(submenu.color);
    padding:0;
    display:block;
    transition:all .17s ease
}
.mobile-menu ul li.has-sub .submenu-toggle{
    position:absolute;
    top:0;
    right:0;
    color:$(submenu.color);
    cursor:pointer
}
.mobile-menu ul li.has-sub .submenu-toggle:after{
    content:'\f105';
    font-family:'Font Awesome 5 Free';
    font-weight:900;
    float:right;
    width:34px;
    font-size:14px;
    text-align:center;
    transition:all .17s ease
}
.mobile-menu ul li.has-sub.show > .submenu-toggle:after{
    transform:rotate(90deg)
}
.mobile-menu > ul > li > ul > li > a{
    color:$(submenu.color);
    opacity:.7;
    padding:0 0 0 15px
}
.mobile-menu > ul > li > ul > li > ul > li > a{
    color:$(submenu.color);
    opacity:.7;
    padding:0 0 0 30px
}
.ad-wrapper .widget > .widget-title {
    display: none;
}
.ad-wrapper {
margin:0 auto;
}
.ad-wrapper .widget-content {
    position:relative;
    max-width:100%;
    max-height:92px;
    line-height:1;
    margin:30px auto 0
}
#prev-ad .widget, #nxt-ad .widget {
    width: 100%;
    margin: 20px 0 0;
    border-top: 1px solid #f2f2f6;
    padding: 15px 0 0;
    box-sizing: border-box;
}
#nxt-ad .widget {
    padding-bottom: 15px;
    margin-bottom: 15px;
    border-bottom: 1px solid #f2f2f6;
}
#home-ad-top2 .widget-content {
margin:0 auto 30px
}
.owl-carousel{
    display:none;
    width:100%;
    -webkit-tap-highlight-color:transparent;
    position:relative;
    z-index:1
}
.owl-carousel .owl-stage{
    position:relative;
    -ms-touch-action:pan-Y
}
.owl-carousel .owl-stage:after{
    content:".";
    display:block;
    clear:both;
    visibility:hidden;
    line-height:0;
    height:0
}
.owl-carousel .owl-stage-outer{
    position:relative;
    overflow:hidden;
    -webkit-transform:translate3d(0px,0px,0px)
}
.owl-carousel .owl-controls .owl-nav .owl-prev,.owl-carousel .owl-controls .owl-nav .owl-next,.owl-carousel .owl-controls .owl-dot{
    cursor:pointer;
    cursor:hand;
    -webkit-user-select:none;
    -khtml-user-select:none;
    -moz-user-select:none;
    -ms-user-select:none;
    user-select:none
}
.owl-carousel.owl-loaded{
    display:block
}
.owl-carousel.owl-loading{
    opacity:0;
    display:block
}
.owl-carousel.owl-hidden{
    opacity:0
}
.owl-carousel .owl-refresh .owl-item{
    display:none
}
.owl-carousel .owl-item{
    position:relative;
    min-height:1px;
    float:left;
    -webkit-backface-visibility:visible;
    -webkit-tap-highlight-color:transparent;
    -webkit-touch-callout:none;
    -webkit-user-select:none;
    -moz-user-select:none;
    -ms-user-select:none;
    user-select:none
}
.owl-carousel.owl-text-select-on .owl-item{
    -webkit-user-select:auto;
    -moz-user-select:auto;
    -ms-user-select:auto;
    user-select:auto
}
.owl-carousel .owl-grab{
    cursor:move;
    cursor:-webkit-grab;
    cursor:-o-grab;
    cursor:-ms-grab;
    cursor:grab
}
.owl-carousel.owl-rtl{
    direction:rtl
}
.owl-carousel.owl-rtl .owl-item{
    float:right
}
.no-js .owl-carousel{
    display:block
}
.owl-carousel .animated{
    -webkit-animation-duration:1000ms;
    animation-duration:1000ms;
    -webkit-animation-fill-mode:both;
    animation-fill-mode:both
}
.owl-carousel .owl-animated-in{
    z-index:1
}
.owl-carousel .owl-animated-out{
    z-index:0
}
.owl-height{
    -webkit-transition:height 500ms ease-in-out;
    -moz-transition:height 500ms ease-in-out;
    -ms-transition:height 500ms ease-in-out;
    -o-transition:height 500ms ease-in-out;
    transition:height 500ms ease-in-out
}
.owl-prev,.owl-next{
    position:relative;
    float:left;
    width:24px;
    height:24px;
    background-color:transparent;
    font-family:'Font Awesome 5 Free';
    font-weight: 900;
    text-rendering: auto;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-size:14px;
    line-height:18px;
    color:$(menu.color);
    text-align:center;
    cursor:pointer;
    border:3px solid rgba(0, 0, 0, 0.15);    
    border-radius: 24px;
    box-sizing:border-box;
    transition:all .25s ease
}
.owl-prev:before{
    content:'\f053'
}
.owl-next:before{
    content:'\f054'
}
.owl-prev:hover,.owl-next:hover{
    border-color: rgba(0, 0, 0, 0.25);
}
#break-wrapper-outer {
    background-color:#555555;
    border-top-left-radius: 7px;
    border-top-right-radius: 7px;
}
#break-wrapper {
    padding: 15px 0;
