/* 목차 박스 스타일 */
#post-toc {
width: 90%;
background: #f4f4f4;  /* 연한 배경 */
padding: 15px;
margin: 20px auto;
border-radius: 1px; /* 둥근 모서리 */
box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.1); /* 살짝 그림자 */
}

/* 목차 제목 */
#post-toc h3 {
font-size: 18px;
margin-bottom: 10px;
color: #000000; /* 검은색 제목 */
text-align: left;
font-weight: bold;
cursor: pointer; /* 클릭 가능한 커서 표시 */
display: flex;
justify-content: flex-start;
align-items: center;
margin: 0;
padding-bottom: 10px;
}

/* 메뉴바 아이콘 추가 */
#post-toc h3:before {
content: &quot;\2630&quot;; /* 메뉴바 아이콘 (Unicode) */
font-size: 18px;
margin-right: 8px;
}

/* 화살표 아이콘 추가 */
#post-toc h3:after {
content: &quot;\25BC&quot;;
font-size: 14px;
margin-left: auto; /* 오른쪽으로 밀어냄 */
transition: transform 0.3s;
}

/* 접혔을 때 화살표 방향 변경 */
#post-toc.collapsed h3:after {
transform: rotate(-180deg);
}

/* 목차 콘텐츠 */
#toc-content {
max-height: 1000px; /* 충분히 큰 값 */
overflow: hidden;
transition: max-height 0.5s ease;
}

/* 접혔을 때 목차 숨김 */
#post-toc.collapsed #toc-content {
max-height: 0;
}

/* 목차 목록 스타일 */
#post-toc ul {
list-style: none;
padding-left: 0;
margin-top: 10px;
}

/* 목차 리스트 스타일 */
#post-toc li {
margin-bottom: 5px;
padding: 5px 10px;
border-left: 4px solid #666666; /* 왼쪽 테두리 강조 */
background: #fff;
transition: all 0.3s ease-in-out;
}

/* 링크 스타일 */
#post-toc a {
text-decoration: none;
color: #333;
font-weight: 500;
}

/* 마우스 호버 효과 */
#post-toc li:hover {
background: #DCDCDC; /* 연한 그레이 */
transform: translateX(5px); /* 오른쪽으로 살짝 이동 */
}
/* 반응형 코드 추가 */
@media screen and (max-width: 768px) {
/* 태블릿 크기 */
#post-toc {
width: 95%;
padding: 12px;
margin: 15px auto;
}

#post-toc h3 {
font-size: 16px;
}

#post-toc li {
padding: 4px 8px;
font-size: 14px;
}
}
@media screen and (max-width: 480px) {
/* 모바일 크기 */
#post-toc {
width: 90%;
padding: 10px;
margin: 10px auto;
border-radius: 0;
}

#post-toc h3 {
font-size: 15px;
}

#post-toc h3:before {
font-size: 16px;
margin-right: 6px;
}

#post-toc h3:after {
font-size: 12px;
}

#post-toc li {
margin-bottom: 3px;
padding: 3px 6px;
border-left: 3px solid #666666;
font-size: 13px;
}

/* 모바일에서는 호버 효과 축소 */
#post-toc li:hover {
transform: translateX(2px);
}
}

/* 매우 작은 화면 대응 */
@media screen and (max-width: 320px) {
#post-toc {
padding: 8px;
}

#post-toc h3 {
font-size: 14px;
}

#post-toc li {
font-size: 12px;
padding: 2px 4px;
}
}
/* 사이드바 컨테이너 */
#left-ads-container {
position: fixed;
top: 80px;
width: 160px;
z-index: 999;
transition: all 0.3s ease;
left: calc((125vw - 1200px) / 2 - 320px + 20px);
}

#right-ads-container {
position: fixed;
top: 400px;
width: 300px;
z-index: 999;
transition: all 0.3s ease;
right: calc((100vw - 1200px) / 2 - 320px + 150px);
}

/* 글(post) 페이지에서만 표시 */
.item #left-ads-container {
display: block;
position: fixed;
top: 80px;
left: calc((115vw - 1200px) / 2 - 320px + 20px);
width: 160px;
z-index: 999;
transition: all 0.3s ease;
}

/* 왼쪽 사이드바 위치 설정 - 기본값 */
#left-ads-container {
left: max(20px, min(270px, (100vw - 900px) / 2 - 20px));
}

/* 오른쪽 사이드바 위치 설정 - 기본값 */
#right-ads-container {
right: max(20px, min(270px, (100vw - 900px) / 2 - 20px));
}

/* 왼쪽 오른쪽 카드 스타일 */
.right-ads-box-card {
width: 300px;
height: 250px;
background: rgba(255, 255, 255, 0);
border-radius: 3px;
overflow: hidden;
position: relative;
font-family: sans-serif;
display: flex;
flex-direction: column;
justify-content: space-between;
transition: all 0.3s ease;
}

.left-ads-box-card {
width: 160px;
height: 600px;
background: rgba(255, 255, 255, 0);
border-radius: 3px;
overflow: hidden;
position: relative;
font-family: sans-serif;
display: flex;
flex-direction: column;
justify-content: space-between;
transition: all 0.3s ease;
}

/* 큰 데스크톱 화면 (1400px 이상) */
@media (min-width: 1401px) {
#right-ads-container {
right: calc((100vw - 1200px) / 2 - 320px + 150px);
width: 300px;
}

#left-ads-container {
left: calc((115vw - 1200px) / 2 - 320px + 20px);
width: 160px;
}

.right-ads-box-card {
width: 300px;
height: 250px;
}

.left-ads-box-card {
width: 160px;
height: 600px;
}
}

/* 데스크톱 화면 (1200px - 1400px) */
@media (min-width: 1201px) and (max-width: 1400px) {
#right-ads-container {
right: calc((110vw - 1100px) / 2 - 320px + 150px);
width: 300px;
}

#left-ads-container {
left: calc((115vw - 1100px) / 2 - 320px + 20px);
width: 160px;
}

.right-ads-box-card {
width: 300px;
height: 250px;
}

.left-ads-box-card {
width: 160px;
height: 600px;
}
}

/* 작은 데스크톱 화면 (992px - 1200px) */
@media (min-width: 992px) and (max-width: 1200px) {
#right-ads-container {
right: 20px;
width: 300px;
}

#left-ads-container {
left: 20px;
width: 160px;
}

.right-ads-box-card {
width: 300px;
height: 250px;
}

.left-ads-box-card {
width: 160px;
height: 600px;
}
}

/* 태블릿 화면 (768px - 991px) */
@media (min-width: 768px) and (max-width: 991px) {
#right-ads-container {
right: 15px;
width: 300px;
}

#left-ads-container {
left: 15px;
width: 300px;
}

.right-ads-box-card,
.left-ads-box-card {
width: 300px;
height: 250px;
}
}

/* 작은 화면 (576px - 767px) */
@media (min-width: 576px) and (max-width: 767px) {
#right-ads-container {
position: static;
width: 100%;
max-width: 200px;
margin: 20px auto;
}

#left-ads-container {
position: static;
width: 100%;
max-width: 200px;
margin: 20px auto;
}

.right-ads-box-card,
.left-ads-box-card {
width: 100%;
}
}

/* 모바일 화면 (575px 이하) */
@media (max-width: 575px) {
#right-ads-container {
position: static;
width: 100%;
margin: 20px auto;
padding: 0 15px;
box-sizing: border-box;
}

#left-ads-container {
position: static;
width: 100%;
margin: 20px auto;
padding: 0 15px;
box-sizing: border-box;
}

.right-ads-box-card,
.left-ads-box-card {
width: 100%;
height: auto;
min-height: 200px;
}
}

/* 작은 화면에서는 사이드바를 콘텐츠 아래에 표시 */
@media (max-width: 1100px) {
#left-ads-container {
display: none !important;
}

#right-ads-container {
position: static;
width: 100%;
max-width: 95%;
}

.right-ads-box-card,
.left-ads-box-card {
margin: 0 auto;
}
}

/* 작은 화면에서는 사이드바를 숨김 */
@media (max-width: 1700px) {
#left-ads-container {
display: none !important;
}

#right-ads-container {
display: none !important;
}
}
.popup-overlay {
position: fixed;
top: 0;
left: 0;
width: 100%;
height: 100%;
background: rgba(0, 0, 0, 0.5);
display: none;
justify-content: center;
align-items: center;
z-index: 9999;
}

.popup-content {
background: white;
width: 90%;
max-width: 350px;
border-radius: 0;
text-align: center;
position: relative;
box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.3);
overflow: hidden;
padding: 0;
}

/* Image container with white space around */
.popup-image-container {
padding: 10px 10px 0 10px;
background: white;
}

/* Image style with border and rounded corners */
.popup-image {
width: 94%;
display: block;
border: 1px solid #ddd;
border-radius: 10px;
padding: 10px;
}

/* Button container with separate styling */
.popup-buttons {
padding: 10px;
background: white;
display: flex;
gap: 10px;
}

/* Button style - base */
.popup-button {
flex: 1;
padding: 15px 0;
text-align: center;
cursor: pointer;
font-size: 16px;
font-weight: 500;
border-radius: 5px;
transition: background 0.2s;
text-decoration: none;
}

/* Close button */
.popup-button-close {
background: #e9e9e9;
color: #333;
}

/* Go button */
.popup-button-go {
background: rgb(0, 123, 255);
color: white;
}

/* Button hover effects */
.popup-button-close:hover {
background: #d9d9d9;
}

.popup-button-go:hover {
background: #3a80d2;
}
/* h2 헤딩 스타일 */
.post-body h2 {
margin: 20px -5px 5px;
font-size: 22px;
font-weight: 700;
COLOR: #333333;
PADDING-BOTTOM: 10px;
TEXT-ALIGN: left;
BORDER-LEFT: #333333 10px solid;
padding: 15px;
BACKGROUND-COLOR: #fafafa;
BORDER-BOTTOM: 2px solid #333333;                          /* 텍스트 왼쪽 정렬 */
}

/* h3 헤딩 스타일 */
.post-body h3 {
margin: 20px -5px 5px;
font-size: 18px;
font-weight: 700;
COLOR: #333333;
PADDING-BOTTOM: 10px;
TEXT-ALIGN: left;
padding: 15px;
BACKGROUND-COLOR: #fafafa;
