/* 🔹 목차 스타일 유지 */
#post-toc {
width: 90%;
background: #f4f4f4;  /* 연한 배경 */
border: 2px solid #1F2024; /* 회색 테두리 */
padding: 15px;
margin: 20px auto;
border-radius: 1px; /* 둥근 모서리 */
box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.1); /* 살짝 그림자 */
}

/* 목차 제목 */
#post-toc h3 {
font-size: 18px;
margin-bottom: 10px;
color: #000000; /* 검은색 제목 */
text-align: center;
font-weight: bold;
cursor: pointer; /* 클릭 가능한 커서 표시 */
display: flex;
justify-content: center;
align-items: center;
margin: 0;
padding-bottom: 10px;
}

/* 화살표 아이콘 추가 */
#post-toc h3:after {
content: &quot;\25BC&quot;;
font-size: 14px;
margin-left: 8px;
transition: transform 0.3s;
}

/* 접혔을 때 화살표 방향 변경 */
#post-toc.collapsed h3:after {
transform: rotate(-180deg);
}

/* 목차 콘텐츠 */
#toc-content {
max-height: 1000px; /* 충분히 큰 값 */
overflow: hidden;
transition: max-height 0.5s ease;
}

/* 접혔을 때 목차 숨김 */
#post-toc.collapsed #toc-content {
max-height: 0;
}

/* 목차 목록 스타일 */
#post-toc ul {
list-style: none;
padding-left: 0;
margin-top: 10px;
}

/* 목차 리스트 스타일 */
#post-toc li {
margin-bottom: 5px;
padding: 5px 10px;
border-left: 4px solid #666666; /* 왼쪽 테두리 강조 */
background: #fff;
transition: all 0.3s ease-in-out;
}

/* 링크 스타일 */
#post-toc a {
text-decoration: none;
color: #333;
font-weight: 500;
}

/* 마우스 호버 효과 */
#post-toc li:hover {
background: #DCDCDC; /* 연한 그레이 */
transform: translateX(5px); /* 오른쪽으로 살짝 이동 */
}

/* 🔹 반응형 스타일 */

/* 태블릿 (768px 이하) */
@media (max-width: 768px) {
.post-body a:not(:has(img)):not(#tocid a):not(#tocify a):not(.tocify-wrap a) {
width: 100%;             /* 버튼 너비 조정 */
font-size: 16px;          /* 글자 크기 약간 줄임 */
padding: 12px 0;          /* 버튼 높이 조정 */
}
}

/* 모바일 (480px 이하) */
@media (max-width: 480px) {
.post-body a:not(:has(img)):not(#tocid a):not(#tocify a):not(.tocify-wrap a) {
width: 100%;            /* 더 좁은 화면에 맞춤 */
font-size: 14px;          /* 글자 크기 조정 */
padding: 10px 0;          /* 높이 줄임 */
border-radius: 6px;       /* 모서리 둥글기 조정 */
}
}
.floating-banner {
position: fixed;
bottom: 10px;
left: 90%;
transform: translateX(-50%);
width: 250px;
background: #6a5acd;
color: white;
border-radius: 10px;
text-align: center;
box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.2);
font-weight: bold;
z-index: 9999;
overflow: hidden;
}

.floating-banner-top img {
width: 95%;
display: flex;
border-radius: 10px 10px 0 0;
margin: 6px auto;
justify-content: center;
}

.floating-banner-bottom {
padding: 12px;
font-size: 14px;
background: #3D0066;
cursor: pointer;
}

.floating-banner-bottom a {
text-decoration: none;
color: white;
display: block;
}

.floating-banner-bottom:hover {
background: #3a2b9d;
}

.floating-close-btn {
position: absolute;
top: 8px;
right: 12px;
background: none;
font-size: 20px;
cursor: pointer;
z-index: 10000;
}

@media screen and (max-width: 600px) {
.floating-banner {
width: 200px;
left: 70%;
}
.floating-banner-bottom {
font-size: 13px;
padding: 10px;
}
}
#latest-posts-section {
margin: 30px 0;
}

#latest-posts-grid {
display: grid;
grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
gap: 16px;
margin-top: 10px;
}

.latest-post-item {
border: none;
border-radius: 0;
overflow: visible;
box-shadow: none;
transition: transform 0.2s ease;
background-color: transparent;
height: 100%;
display: flex;
flex-direction: column;
}

.latest-post-item:hover {
transform: translateY(-2px);
box-shadow: none;
}

.latest-post-item .image-container {
width: 100%;
padding-top: 100%; /* 1:1 비율 (정사각형) */
position: relative;
overflow: hidden;
border-radius: 8px;
}

.latest-post-item img {
position: absolute;
top: 0;
left: 0;
width: 100%;
height: 100%;
object-fit: cover;
transition: transform 0.3s ease;
border-radius: 8px;
}

.latest-post-item:hover img {
transform: scale(1.05);
}

.latest-post-item p {
padding: 8px 2px;
margin: 0;
font-size: 14px;
color: #333;
font-weight: 500;
flex-grow: 1;
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
text-overflow: ellipsis;
line-height: 1.4; max-height: 2.8em;
}

.latest-post-item a {
text-decoration: none;
color: inherit;
display: flex;
flex-direction: column;
height: 100%;
}

/* 태블릿 반응형 */
@media screen and (max-width: 768px) {
#latest-posts-grid {
grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
gap: 12px;
}

.latest-post-item p {
font-size: 13px;
padding: 6px 2px;
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
text-overflow: ellipsis;
line-height: 1.4;
max-height: 2.8em;
}
}

/* 모바일 반응형 */
@media screen and (max-width: 480px) {
#latest-posts-grid {
grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
gap: 10px;
}

.latest-post-item .image-container {
padding-top: 100%; /* 1:1 비율 유지 */
border-radius: 6px;
}

.latest-post-item img {
border-radius: 6px;
}

.latest-post-item p {
padding: 6px 2px;
font-size: 14px;
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
text-overflow: ellipsis;
line-height: 1.4;
max-height: 2.8em;
}
}

/* 아주 작은 화면 대응 */
@media screen and (max-width: 320px) {
#latest-posts-grid {
grid-template-columns: repeat(2, 1fr);
gap: 8px;
}

.latest-post-item .image-container {
padding-top: 100%;
}

.latest-post-item p {
font-size: 11px;
padding: 4px 2px;
display: -webkit-box;
-webkit-line-clamp: 2;
-webkit-box-orient: vertical;
overflow: hidden;
text-overflow: ellipsis;
line-height: 1.4;
max-height: 2.8em;
}
}
.share-buttons-container {
display: grid;
grid-template-columns: 1fr 1fr;
gap: 10px;
padding: 15px 0;
margin: 20px 0;
border-top: 1px solid #eee;
border-bottom: 1px solid #eee;
width: 100%;
}

.share-button {
display: flex;
align-items: center;
justify-content: center;
gap: 10px;
background: #f5f5f5;
border: none;
cursor: pointer;
font-size: 15px;
color: #fff;
padding: 15px 0;
border-radius: 4px;
transition: all 0.2s ease;
font-weight: 500;
width: 100%;
}

.share-button:hover {
opacity: 0.9;
}

.share-link {
background-color: #3498db;
}

.share-common {
background-color: #e74c3c;
}

.navy-bar {
    width: 100%;
    height: 35px;
    background-color: #001f4d;
    text-align: center;
    }

/* 헤더 강제 고정 (애드센스 앵커 광고 대응) - 배경색 변경 없음 */
#header-wrap {
    position: fixed !important;
    top: 0 !important;
    left: 0;
    width: 100%;
    z-index: 1001 !important;
}

/* 헤더 고정으로 인한 콘텐츠 본문 상단 여백 추가 (애드센스 간섭 방지) */
body {
    padding-top: 70px !important;
}

@media screen and (max-width: 980px) {
    body {
        padding-top: 60px !important;
    }
}
/* ===== 애드센스 전면광고 보호 스타일 ===== */
.google-auto-placed, .adsbygoogle-noablate, #google_image_div, #google_vignette_modal { z-index: 2147483647 !important; }
ins.adsbygoogle iframe, .google-auto-placed iframe { max-width: none !important; max-height: none !important; padding: 0 !important; margin: 0 !important; }
#google_esf_iframe { z-index: 2147483647 !important; }
ins.adsbygoogle { background: transparent !important; text-decoration: none !important; }

b:if.b:template-skin:
/*------Layout (No Edit)----------*/
body#layout #outer-wrapper,body#layout .row{width:auto;padding:0}
body#layout{width:800px;position:relative;padding:95px 5px 0;margin:0}
body#layout div.section{margin:0 5px 10px!important;padding:16px 16px 18px!important}
body#layout .section h4{font-size:14px;margin:0}
body#layout .layout-widget-description{display:none}
body#layout .theme-options,body#layout #main-menu .widget{display:block!important}
body#layout div.sora-panel{background-color:#d7d7d7!important;overflow:hidden!important;border-color:#bcbcbc}
body#layout .sora-panel .widget{float:left;width:49%;margin-right:2%}
body#layout .sora-panel #LinkList71{margin-right:0}
body#layout #header-wrap {
clear:both;
}
body#layout #header-wrap{height:auto}
body#layout .header-header{float:left;width:100%;height:auto;padding:0}
body#layout .header-header .container{display:flex}
body#layout div.header-logo,body#layout div.main{float:none}
body#layout #header-wrap > .container{display:flex}
body#layout div.header-logo,body#layout div.header-menu{float:none;width:50%;max-width:none;max-height:none;margin:0}
body#layout .main-logo{float:none;max-width:none;max-height:none}
body#layout .mobile-menu-wrap,body#layout .show-search{display:none}
body#layout #main-menu{height:auto}
body#layout #break-wrapper .widget {
    display: block;
}
body#layout #content-wrapper{margin:0}
body#layout #content-wrapper > .container{display:flex;margin:0}
body#layout #main-wrapper{width:66.66%;padding:0}
body#layout .footer-widgets-wrap{display:flex}
body#layout .footer-widgets-wrap div.footer{width:100%}
body#layout .home-ad .widget-content{float:none;width:auto;margin:0}
body#layout #hot-wrapper .widget{display:block}
body#layout .primary-footer {
    display: flex;
}
body#layout .footer-about-area, body#layout .foot-bar-social {
    width: 100%;
    float: left;
    display: block;
}
/*------Layout (end)----------*/

