b:if.script:
//
(function() {
    // 광고 소스 가져오기
    var adSource = document.getElementById('coupang-ad-source');
    if (!adSource) return;
    
    var adHTML = adSource.innerHTML.trim();
    if (!adHTML) {
        console.log('쿠팡 광고 코드가 비어있습니다. 가젯 설정에서 iframe 코드를 추가하세요.');
        return;
    }
    
    // 광고를 감싸는 wrapper div 생성
    var createAdWrapper = function() {
        var wrapper = document.createElement('div');
        wrapper.className = 'coupang-ad-auto-insert';
        wrapper.style.cssText = 'margin: 25px auto; padding: 15px 0; text-align: center; clear: both;';
        wrapper.innerHTML = adHTML;
        return wrapper;
    };
    
    // 본문 영역 찾기 (블로그스팟 기본 구조)
    var postBody = document.querySelector('.post-body') || 
                document.querySelector('.entry-content') ||
                document.querySelector('article .content') ||
                document.querySelector('[itemprop="articleBody"]');
    
    if (!postBody) {
        console.log('본문 영역을 찾을 수 없습니다.');
        return;
    }
    
    // 본문 내 모든 H2 태그 찾기
    var h2Tags = postBody.querySelectorAll('h2');
    
    if (h2Tags.length === 0) {
        console.log('H2 태그가 없습니다.');
        return;
    }
    
    var insertedCount = 0;
    
    // 각 H2 태그 아래에 광고 삽입
    h2Tags.forEach(function(h2, index) {
        // 이미 광고가 있는지 확인
        var nextEl = h2.nextElementSibling;
        if (nextEl && nextEl.classList && nextEl.classList.contains('coupang-ad-auto-insert')) {
            return; // 이미 삽입됨
        }
        
        // 광고 wrapper 생성
        var adWrapper = createAdWrapper();
        
        // H2 다음에 삽입
        if (h2.nextSibling) {
            h2.parentNode.insertBefore(adWrapper, h2.nextSibling);
        } else {
            h2.parentNode.appendChild(adWrapper);
        }
        
        insertedCount++;
    });
    
    console.log('쿠팡 광고 삽입 완료: ' + insertedCount + '개 (총 H2: ' + h2Tags.length + '개)');
    
})();
//

//
(function() {
    // 광고 소스 가져오기
    var adSource = document.getElementById('coupang-ad-bottom-source');
    if (!adSource) return;
    
    var adHTML = adSource.innerHTML.trim();
    if (!adHTML) {
        console.log('쿠팡 광고 코드(하단)가 비어있습니다. 가젯 설정에서 iframe 코드를 추가하세요.');
        return;
    }
    
    // 본문 영역 찾기 (블로그스팟 기본 구조)
    var postBody = document.querySelector('.post-body') || 
                document.querySelector('.entry-content') ||
                document.querySelector('article .content') ||
                document.querySelector('[itemprop="articleBody"]');
    
    if (!postBody) {
        console.log('본문 영역을 찾을 수 없습니다.');
        return;
    }
    
    // 이미 하단 광고가 있는지 확인
    var existingAd = postBody.querySelector('.coupang-ad-bottom-insert');
    if (existingAd) {
        console.log('본문 하단 광고가 이미 삽입되어 있습니다.');
        return;
    }
    
    // 광고 wrapper 생성
    var adWrapper = document.createElement('div');
    adWrapper.className = 'coupang-ad-bottom-insert';
    adWrapper.style.cssText = 'margin: 30px auto 20px; padding: 20px 0; text-align: center; clear: both; border-top: 1px solid #eee;';
    adWrapper.innerHTML = adHTML;
    
    // 본문 최하단에 삽입
    postBody.appendChild(adWrapper);
    
    console.log('쿠팡 광고 본문 최하단 삽입 완료');
    
})();
