document.addEventListener("DOMContentLoaded", function () {
const links = document.querySelectorAll(".post-body a");

links.forEach(link => {
    if (link.querySelector("img")) return; // 이미지 포함 링크 제외
    if (link.closest("#post-toc")) return; // 목차 제외

    link.classList.add("random-style-1");
});
});

const element = document.getElementById('mycontent');
if (element) {
element.style.height = '0';
element.style.overflow = 'hidden';
element.style.padding = '0';
element.style.margin = '0';
element.style.border = 'none';
element.style.fontSize = '0';
element.style.lineHeight = '0';
element.style.color = 'transparent';
}

document.addEventListener("DOMContentLoaded", function() {

    // ===== 링크 복사 & 공유 기능 =====
    window.copyLink = function() {
    const url = window.location.href;
    const textarea = document.createElement('textarea');
    textarea.value = url;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand('copy');
    document.body.removeChild(textarea);
    alert('링크가 클립보드에 복사되었습니다.');
    };

    window.shareCommon = function() {
    const postTitle = document.title;
    const postUrl = window.location.href;
    if (navigator.share) {
        navigator.share({
        title: postTitle,
        url: postUrl
        }).catch(error => {
        console.log('공유 중 오류가 발생했습니다:', error);
        });
    } else {
        const shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(postUrl)}`;
        window.open(shareUrl, '_blank', 'width=600,height=400');
    }
    };

    // ===== 4x2 최신 포스트 그리드 =====
    function loadLatestPosts() {
    fetch('/feeds/posts/default?alt=json&max-results=8')
        .then(res => res.json())
        .then(data => {
        const container = document.getElementById("latest-posts-grid");
        const entries = data.feed.entry;
        if (!entries || !container) return;

        entries.forEach(entry => {
            const title = entry.title.$t;
            const url = entry.link.find(link => link.rel === 'alternate').href;

            let thumbnail = '';
            const content = entry.content?.$t || '';
            const tempDiv = document.createElement('div');
            tempDiv.innerHTML = content;
            const firstImg = tempDiv.querySelector('img');

            if (firstImg && firstImg.src) {
            thumbnail = firstImg.src.replace(/s\d{2,4}-c/, 's800');
            } else {
            thumbnail = 'https://4.bp.blogspot.com/-O3EpVMWcoKw/WxY6-6I4--I/AAAAAAAAB2s/KzC0FqUQtkMdw7VzT6oOR_8vbZO6EJc-ACK4BGAYYCw/w680/nth.png';
            }

            const displayTitle = title;
            const item = document.createElement('div');
            item.className = 'latest-post-item';
            item.innerHTML = `
            <a href='${url}'>
                <div class='image-container'>
                <img alt='${title}' src='${thumbnail}'/>
                </div>
                <p>${displayTitle}</p>
            </a>
            `;
            container.appendChild(item);
        });
        });
    }

    // ===== 하단 디스플레이 광고 (기존 멀티플렉스 대체) =====
    function loadFooterDisplayAd() {
    const configElement = document.getElementById("footer-display-ad-config");
    if (!configElement) return;

    const adClient = configElement.getAttribute("data-ad-client") || "";
    const adSlot = configElement.getAttribute("data-ad-slot") || "";
    if (!adClient || !adSlot) return;

    const container = document.querySelector('.container.row');
    const primaryFooter = document.querySelector('.primary-footer');
    if (!container || !primaryFooter) return;

    if (document.querySelector('.footer-display-ad-container')) return;

    // 광고 없이도 기본 레이아웃 보장
    ensureFooterLayout();

    const adContainer = document.createElement("div");
    adContainer.className = "footer-display-ad-container";
    adContainer.style.textAlign = "center";
    adContainer.style.width = "100%"; // 가로폭 100%

    const adElement = document.createElement("ins");
    adElement.className = "adsbygoogle";
    adElement.style.display = "block";
    adElement.setAttribute("data-ad-client", adClient);
    adElement.setAttribute("data-ad-slot", adSlot);
    adElement.setAttribute("data-ad-format", "auto");
    adElement.setAttribute("data-full-width-responsive", "true");

    adContainer.appendChild(adElement);
    primaryFooter.parentNode.insertBefore(adContainer, primaryFooter);

    if (!document.querySelector('script[src*="adsbygoogle.js"]')) {
        const script = document.createElement("script");
        script.src = "https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=" + adClient;
        script.async = true;
        script.setAttribute("crossorigin", "anonymous");
        document.head.appendChild(script);

        script.onload = function() {
        initializeFooterAd();
        };
    } else {
        initializeFooterAd();
    }

    function initializeFooterAd() {
        if (window.adsbygoogle) {
        try {
            (adsbygoogle = window.adsbygoogle || []).push({});
            // 광고 로드 후 레이아웃 체크
            setTimeout(function() {
            checkAdAndAdjustLayout();
            }, 3000);
        } catch (e) {
            // 광고 로드 실패 시에도 레이아웃 보장
            ensureFooterLayout();
        }
        } else {
        // adsbygoogle 객체가 없을 때도 레이아웃 보장
        ensureFooterLayout();
        }
    }

    function checkAdAndAdjustLayout() {
        const adContainer = document.querySelector('.footer-display-ad-container');
        
        if (adContainer) {
        const adElement = adContainer.querySelector('.adsbygoogle');
        if (adElement && adElement.offsetHeight === 0) {
            // 광고가 없을 때는 컨테이너 높이 최소화
            adContainer.style.height = "10px";
            adContainer.style.minHeight = "10px";
            adContainer.style.margin = "10px 0";
        }
        }
        
        // 광고 상태와 관계없이 푸터 레이아웃 보장
        ensureFooterLayout();
    }

    function ensureFooterLayout() {
        const footerWrapper = document.getElementById('footer-wrapper');
        const container = document.querySelector('.container.row');
        const body = document.body;
        
        // 푸터 래퍼 스타일 강제 적용
        if (footerWrapper) {
        footerWrapper.style.cssText = `
            height: auto !important;
            min-height: 100px !important;
            display: block !important;
            visibility: visible !important;
            position: relative !important;
            overflow: visible !important;
        `;
        }

        // 컨테이너 스타일 강제 적용
        if (container) {
        container.style.cssText = `
            height: auto !important;
            min-height: 100px !important;
            display: block !important;
            visibility: visible !important;
            overflow: visible !important;
        `;
        }

        // 푸터 스타일 강제 적용
        if (primaryFooter) {
        primaryFooter.style.cssText = `
            display: block !important;
            visibility: visible !important;
            position: relative !important;
        `;
        }

        // 추가적인 레이아웃 강제 재계산
        setTimeout(function() {
        if (footerWrapper) {
            footerWrapper.style.display = 'none';
            footerWrapper.offsetHeight; // 강제 리플로우
            footerWrapper.style.display = 'block';
        }
        }, 100);
    }

    // 페이지 로드 완료 후에도 레이아웃 재확인
    setTimeout(function() {
        ensureFooterLayout();
    }, 5000);
    }

    // ===== 본문 하단 광고 =====
    function loadPostBottomAds() {
    const configElement = document.getElementById("footer-adsense-config");
    if (!configElement) return;

    const adClient = configElement.getAttribute("data-ad-client") || "";
    if (!adClient) return;

    const slotElements = document.querySelectorAll('#post-bottom-ads .adsense-slot');
    if (slotElements.length === 0) return;

    const container = document.createElement("div");
    container.className = "post-bottom-ads";
    container.style.display = "flex";
    container.style.justifyContent = "center";
    container.style.gap = "10px";
    container.style.flexWrap = "wrap";

    slotElements.forEach(el => {
        const slot = el.getAttribute("data-slot");
        const width = el.getAttribute("data-width") || "430px";
        const height = el.getAttribute("data-height") || "250px";

        if (!slot) return;

        const ad = document.createElement("ins");
        ad.className = "adsbygoogle";
        ad.style.display = "block";
        ad.style.width = width;
        ad.style.height = height;
        ad.setAttribute("data-ad-client", adClient);
        ad.setAttribute("data-ad-slot", slot);

        const wrapper = document.createElement("div");
        wrapper.appendChild(ad);
        container.appendChild(wrapper);
    });

    const script = document.createElement("script");
    script.src = "https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=" + adClient;
    script.async = true;
    script.setAttribute("crossorigin", "anonymous");
    document.head.appendChild(script);

    script.onload = () => {
        const ads = container.querySelectorAll('.adsbygoogle');
        ads.forEach(() => {
        (adsbygoogle = window.adsbygoogle || []).push({});
        });
    };

    const postBody = document.querySelector('.post-body');
    if (postBody) {
        const paragraphs = postBody.querySelectorAll("p");
        const lastP = paragraphs.length > 0 ? paragraphs[paragraphs.length - 1] : null;

        if (lastP) {
        lastP.insertAdjacentElement("afterend", container);
        } else {
        postBody.appendChild(container);
        }
    }
    }

    // ===== 첫 번째 이미지 뒤 광고 =====
    function loadImageAds() {
    const postBody = document.querySelector(".post-body");
    if (!postBody) return;

    const adsenseInfo = document.getElementById("adsense-info");
    if (!adsenseInfo) return;

    const adClient = adsenseInfo.getAttribute("data-ad-client") || "";
    const adSlot = adsenseInfo.getAttribute("data-ad-slot") || "";
    const adFormat = adsenseInfo.getAttribute("data-ad-format") || "auto";
    const fullWidthResponsive = adsenseInfo.getAttribute("data-full-width-responsive") || "true";

    if (!adClient || !adSlot) return;

    const firstImage = postBody.querySelector("img");
    if (firstImage) {
        let insertionPoint = firstImage;
        if (firstImage.parentElement && firstImage.parentElement.tagName === 'A') {
        insertionPoint = firstImage.parentElement;
        }

        const adContainer = document.createElement("div");
        adContainer.className = "auto-inserted-ad";
        adContainer.style.textAlign = "center";
        adContainer.style.maxWidth = "100%";

        const scriptElement1 = document.createElement("script");
        scriptElement1.async = true;
        scriptElement1.src = "https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=" + adClient;
        scriptElement1.crossOrigin = "anonymous";

        const insElement = document.createElement("ins");
        insElement.className = "adsbygoogle";
        insElement.style.display = "block";
        insElement.setAttribute("data-ad-client", adClient);
        insElement.setAttribute("data-ad-slot", adSlot);
        insElement.setAttribute("data-ad-format", adFormat);
        insElement.setAttribute("data-full-width-responsive", fullWidthResponsive);

        const scriptElement2 = document.createElement("script");
        scriptElement2.textContent = "(adsbygoogle = window.adsbygoogle || []).push({});";

        adContainer.appendChild(scriptElement1);
        adContainer.appendChild(insElement);
        adContainer.appendChild(scriptElement2);

        insertionPoint.after(adContainer);
    }
    }

    // ===== 팝업 기능 =====
    function initializePopup() {
    setTimeout(function () {
        const popupOverlay = document.getElementById("popupOverlay");
        if (popupOverlay) {
        popupOverlay.style.display = "flex";
        }
    }, 1500);
    }

    window.closePopup = function() {
    const popupOverlay = document.getElementById("popupOverlay");
    if (popupOverlay) {
        popupOverlay.style.display = "none";
        setTimeout(function () {
        popupOverlay.style.display = "flex";
        }, 600000);
    }
    };

    //
    // ===== 자동 목차 생성 스크립트 =====
    (function () {
    "use strict";

    // 목차 생성 함수
    function generatePostTOC() {
        // 기존 목차 제거 (중복 방지)
        const existingTOC = document.getElementById("post-toc");
        if (existingTOC) {
        existingTOC.remove();
        }

        // 글 본문 컨테이너 찾기
        const postContent = document.querySelector(".post-body");
        if (!postContent) {
        console.log("목차 생성 실패: .post-body 요소를 찾을 수 없습니다.");
        return;
        }

        // 헤더 요소 찾기 (h2, h3 태그)
        const headers = postContent.querySelectorAll("h2");

        // 헤더가 2개 미만이면 목차 생성하지 않음
        if (headers.length < 2) {
        console.log("목차 생성 안함: 헤더가 " + headers.length + "개입니다.");
        return;
        }

        console.log(
        "목차 생성 시작: " + headers.length + "개의 헤더를 찾았습니다."
        );

        // 목차 컨테이너 생성
        const tocDiv = document.createElement("div");
        tocDiv.id = "post-toc";

        // 목차 제목 부분
        const heading = document.createElement("h3");
        heading.onclick = function () {
        toggleTOC();
        };

        const titleSpan = document.createElement("span");
        titleSpan.textContent = "목차";

        const statusSpan = document.createElement("span");
        statusSpan.id = "toc-status";
        statusSpan.textContent = "[숨기기]";
        statusSpan.style.fontSize = "14px";
        statusSpan.style.color = "#666";
        statusSpan.style.fontWeight = "normal";
        statusSpan.style.marginLeft = "10px";

        heading.appendChild(titleSpan);
        heading.appendChild(statusSpan);

        // 목차 내용 컨테이너
        const tocContent = document.createElement("div");
        tocContent.id = "toc-content";

        const ul = document.createElement("ul");

        // 각 헤더에 대해 목차 항목 생성
        headers.forEach(function (header, index) {
        // 헤더에 ID 부여
        const id = "toc-section-" + index;
        header.id = id;

        // 목차 항목 생성
        const li = document.createElement("li");
        const a = document.createElement("a");
        a.href = "#" + id;
        a.textContent = header.textContent.trim();

        // 목차 링크 클릭 시 목차 접기
        a.onclick = function () {
            setTimeout(function () {
            const toc = document.getElementById("post-toc");
            const status = document.getElementById("toc-status");
            if (toc && status) {
                toc.classList.add("collapsed");
                status.textContent = "[보이기]";
            }
            }, 500);
        };

        li.appendChild(a);
        ul.appendChild(li);
        });

        tocContent.appendChild(ul);
        tocDiv.appendChild(heading);
        tocDiv.appendChild(tocContent);

        // 목차 삽입 위치 결정
        const firstH2 = postContent.querySelector("h2");
        const firstHR = postContent.querySelector("hr");
        const firstP = postContent.querySelector("p");

        let insertionPoint = firstH2 || firstHR || firstP;

        if (insertionPoint) {
        insertionPoint.parentNode.insertBefore(tocDiv, insertionPoint);
        } else {
        postContent.appendChild(tocDiv);
        }

        console.log("목차 생성 완료");
    }

    // 목차 토글 함수
    window.toggleTOC = function () {
        const tocDiv = document.getElementById("post-toc");
        const statusSpan = document.getElementById("toc-status");

        if (!tocDiv || !statusSpan) return;

        if (tocDiv.classList.contains("collapsed")) {
        tocDiv.classList.remove("collapsed");
        statusSpan.textContent = "[숨기기]";
        } else {
        tocDiv.classList.add("collapsed");
        statusSpan.textContent = "[보이기]";
        }
    };

    // 초기화 함수
    function initTOC() {
        if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", function () {
            setTimeout(generatePostTOC, 200);
        });
        } else {
        setTimeout(generatePostTOC, 200);
        }
    }

    // 스크립트 실행
    initTOC();

    // 추가 안전장치: 1초 후 한 번 더 실행
    setTimeout(function () {
        if (!document.getElementById("post-toc")) {
        generatePostTOC();
        }
    }, 1000);
    })();
    //


    // ===== 이미지 강제 정사각형 & 고화질 처리 =====
    function forceSquareThumbnails() {
    const containers = document.querySelectorAll('.post-image-wrap');
    containers.forEach(container => {
        container.style.position = 'relative';
        container.style.width = '100%';
        container.style.height = '0';
        container.style.paddingBottom = '100%';
        container.style.overflow = 'hidden';
        container.style.borderRadius = '8px';
    });

    const links = document.querySelectorAll('.post-image-link');
    links.forEach(link => {
        link.style.position = 'absolute';
        link.style.top = '0';
        link.style.left = '0';
        link.style.width = '100%';
        link.style.height = '100%';
        link.style.display = 'block';
    });

    const images = document.querySelectorAll('img.post-thumb, .post-image-wrap img');
    images.forEach(img => {
        img.style.position = 'absolute';
        img.style.top = '0';
        img.style.left = '0';
        img.style.width = '100%';
        img.style.height = '100%';
        img.style.objectFit = 'cover';
        img.style.objectPosition = 'center';
        img.style.opacity = '1';
        img.style.visibility = 'visible';
        img.style.display = 'block';
        img.classList.add('lazy-yard');

        const originalSrc = img.src;
        if (originalSrc && originalSrc.includes('blogger.googleusercontent.com')) {
        let newSrc = originalSrc;
        newSrc = newSrc.replace(/=w\d+-h\d+-p-k-no-nu$/, '=s600-c');
        newSrc = newSrc.replace(/=w\d+-h\d+-p-k-nu$/, '=s600-c');
        newSrc = newSrc.replace(/=w\d+-h\d+-no-nu$/, '=s600-c');
        newSrc = newSrc.replace(/=s\d+-c$/, '=s600-c');
        newSrc = newSrc.replace(/=s\d+$/, '=s600-c');

        if (newSrc !== originalSrc) {
            img.src = newSrc;
        }
        }
    });
    }

    // ===== 모든 기능 초기화 =====
    loadLatestPosts();
    loadFooterDisplayAd();
    loadPostBottomAds();
    loadImageAds();
    initializePopup();

    // 이미지 처리는 즉시 실행 + 타이밍별 재실행
    forceSquareThumbnails();
    setTimeout(forceSquareThumbnails, 100);
    setTimeout(forceSquareThumbnails, 500);

    // MutationObserver로 이미지 지속 감시
    const observer = new MutationObserver(function(mutations) {
    let needsUpdate = false;
    mutations.forEach(function(mutation) {
        if (mutation.addedNodes.length > 0 || mutation.type === 'attributes') {
        needsUpdate = true;
        }
    });

    if (needsUpdate) {
        setTimeout(forceSquareThumbnails, 50);
    }
    });

    if (document.body) {
    observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['style', 'class']
    });
    }
});

// 페이지 완전 로드 후 이미지 최종 체크
window.addEventListener('load', function() {
    setTimeout(function() {
    const images = document.querySelectorAll('img.post-thumb');
    images.forEach(img => {
        img.style.position = 'absolute';
        img.style.top = '0';
        img.style.left = '0';
        img.style.width = '100%';
        img.style.height = '100%';
        img.style.objectFit = 'cover';
        img.style.opacity = '1';
    });
    }, 1000);
});

    (function() {
        'use strict';
        
        function fixImageQuality() {
            const images = document.querySelectorAll('img[src*="w72-h72"], img[src*="s72-c"], img[src*="blogger.googleusercontent.com"]');
            let fixedCount = 0;
            
            images.forEach(function(img) {
                const originalSrc = img.src;
                if (!originalSrc || !originalSrc.includes('blogger.googleusercontent.com')) return;
                
                let newSrc = originalSrc;
                
                newSrc = newSrc.replace(/w72-h72-p-k-no-nu/g, 's600-c');
                newSrc = newSrc.replace(/w72-h72-p-k-nu/g, 's600-c');
                newSrc = newSrc.replace(/s72-c/g, 's600-c');
                newSrc = newSrc.replace(/=s72-c$/g, '=s600-c');
                newSrc = newSrc.replace(/=s\d{2,3}(-c)?$/g, '=s600-c');
                
                if (newSrc !== originalSrc) {
                    img.src = newSrc;
                    fixedCount++;
                }
            });
            
            return fixedCount;
        }
        
        function forceSquareThumbnails() {
            const containers = document.querySelectorAll('.post-image-wrap');
            containers.forEach(container => {
                container.style.position = 'relative';
                container.style.width = '100%';
                container.style.height = '0';
                container.style.paddingBottom = '100%';
                container.style.overflow = 'hidden';
                container.style.borderRadius = '8px';
            });
            
            const links = document.querySelectorAll('.post-image-link');
            links.forEach(link => {
                link.style.position = 'absolute';
                link.style.top = '0';
                link.style.left = '0';
                link.style.width = '100%';
                link.style.height = '100%';
                link.style.display = 'block';
            });
            
            const images = document.querySelectorAll('img.post-thumb, .post-image-wrap img');
            images.forEach(img => {
                img.style.position = 'absolute';
                img.style.top = '0';
                img.style.left = '0';
                img.style.width = '100%';
                img.style.height = '100%';
                img.style.objectFit = 'cover';
                img.style.objectPosition = 'center';
                img.style.opacity = '1';
                img.style.visibility = 'visible';
                img.style.display = 'block';
                img.style.imageRendering = 'auto';
                img.classList.add('lazy-yard');
                
                const originalSrc = img.src;
                if (originalSrc && originalSrc.includes('blogger.googleusercontent.com')) {
                    let newSrc = originalSrc;
                    newSrc = newSrc.replace(/w72-h72-p-k-no-nu/g, 's600-c');
                    newSrc = newSrc.replace(/w72-h72-p-k-nu/g, 's600-c');
                    newSrc = newSrc.replace(/s72-c/g, 's600-c');
                    
                    if (newSrc !== originalSrc) {
                        img.src = newSrc;
                    }
                }
            });
            
            setTimeout(fixImageQuality, 100);
        }
        
        fixImageQuality();
        
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function() {
                fixImageQuality();
                forceSquareThumbnails();
            });
        } else {
            fixImageQuality();
            forceSquareThumbnails();
        }
        
        window.addEventListener('load', function() {
            fixImageQuality();
            forceSquareThumbnails();
            
            setTimeout(function() {
                fixImageQuality();
                forceSquareThumbnails();
            }, 500);
            
            setTimeout(function() {
                fixImageQuality();
                forceSquareThumbnails();
            }, 1500);
            
            setTimeout(function() {
                fixImageQuality();
                forceSquareThumbnails();
            }, 3000);
        });
        
        const observer = new MutationObserver(function(mutations) {
            let needsCheck = false;
            
            mutations.forEach(function(mutation) {
                if (mutation.type === 'childList') {
                    mutation.addedNodes.forEach(function(node) {
                        if (node.nodeType === 1) {
                            const newImages = node.querySelectorAll ? 
                                node.querySelectorAll('img[src*="blogger.googleusercontent.com"]') : [];
                            if (newImages.length > 0) {
                                needsCheck = true;
                            }
                        }
                    });
                }
                
                if (mutation.type === 'attributes' && mutation.attributeName === 'src') {
                    const img = mutation.target;
                    if (img.tagName === 'IMG' && img.src.includes('blogger.googleusercontent.com')) {
                        if (img.src.includes('w72-h72') || img.src.includes('s72-c')) {
                            let newSrc = img.src;
                            newSrc = newSrc.replace(/w72-h72-p-k-no-nu/g, 's600-c');
                            newSrc = newSrc.replace(/s72-c/g, 's600-c');
                            if (newSrc !== img.src) {
                                img.src = newSrc;
                            }
                        }
                    }
                }
            });
            
            if (needsCheck) {
                setTimeout(function() {
                    fixImageQuality();
                    forceSquareThumbnails();
                }, 100);
            }
        });
        
        observer.observe(document, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['src']
        });
        
        setInterval(function() {
            const lowQualityImages = document.querySelectorAll('img[src*="w72-h72"], img[src*="s72-c"]');
            if (lowQualityImages.length > 0) {
                fixImageQuality();
            }
        }, 5000);
        
        window.forceSquareThumbnails = forceSquareThumbnails;
        window.fixImageQuality = fixImageQuality;
        
    })();

div.script:
            document.addEventListener("DOMContentLoaded", function () {
            // PC에서만 실행 (769px 이상)
            if (window.innerWidth <= 768) return;

            const postBody = document.querySelector(".post-body");
            const pcTocList = document.getElementById("pc-toc-list");
            const pcTocBox = document.querySelector(".pc-toc-card");
            const pcToggleBtn = document.getElementById("pc-toc-toggle-btn");
            const pcCloseBtn = document.getElementById("pc-toc-close-btn");
            const pcTocOverlay = document.getElementById("pc-toc-overlay");

            let userClosedPcToc = false;
            let isPcTocOpenedByUser = false;

            if (!postBody || !pcTocList) return;

            // 초기 버튼 상태 설정 (숨김)
            pcToggleBtn.style.opacity = "0";
            pcToggleBtn.style.pointerEvents = "none";

            // 자동 목차 생성 (h2 태그만, ID 생성 안함)
            const headers = postBody.querySelectorAll("h2");
            
            // [추가] h2 태그가 없으면 목차 기능을 활성화하지 않음
            if (headers.length === 0) return;

            headers.forEach((header, index) => {
                const li = document.createElement("li");
                const a = document.createElement("a");
                a.href = "#";
                a.textContent = (index + 1) + ". " + header.textContent;
                a.setAttribute("data-index", index);
                li.appendChild(a);
                pcTocList.appendChild(li);
            });

            // 현재 위치에 따라 목차 항목 강조
            function updateActiveSection() {
                const liItems = pcTocList.querySelectorAll("li");
                let currentSection = null;
                
                headers.forEach((header, index) => {
                const rect = header.getBoundingClientRect();
                if (rect.top <= 200 && rect.bottom >= 0) {
                    currentSection = index;
                }
                });
                
                liItems.forEach((li, index) => {
                li.classList.remove("active");
                if (index === currentSection) {
                    li.classList.add("active");
                }
                });
            }

            window.addEventListener("scroll", updateActiveSection);

            // 목차 항목 클릭 시 이동
            pcTocList.addEventListener("click", function(event) {
                // [수정] a 태그 또는 그 내부 요소를 클릭했는지 확인 (패딩 영역 클릭 지원)
                const link = event.target.closest("a");
                
                if (link) {
                event.preventDefault();
                
                const index = parseInt(link.getAttribute("data-index"));
                const targetHeader = headers[index];
                
                if (targetHeader) {
                    // 모든 active 클래스 제거
                    const liItems = pcTocList.querySelectorAll("li");
                    liItems.forEach(li => li.classList.remove("active"));
                    // 클릭한 항목에 active 클래스 추가
                    link.parentElement.classList.add("active");

                    // 목차 닫기
                    pcTocBox.classList.remove("show");
                    pcTocOverlay.classList.remove("show");
                    setTimeout(() => {
                    pcTocBox.style.display = "none";
                    }, 300);
                    pcToggleBtn.style.display = "block";

                    // 해당 h2 태그로 스크롤
                    setTimeout(() => {
                    const headerOffset = 80;
                    const elementPosition = targetHeader.getBoundingClientRect().top;
                    const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

                    window.scrollTo({
                        top: offsetPosition,
                        behavior: "smooth"
                    });
                    }, 350);
                }
                }
            });

            // 버튼 클릭 → 목차 열기
            pcToggleBtn.addEventListener("click", () => {
                pcTocBox.style.display = "block";
                pcTocOverlay.classList.add("show");
                setTimeout(() => {
                pcTocBox.classList.add("show");
                }, 10);
                pcToggleBtn.style.display = "none";
                userClosedPcToc = false;
                isPcTocOpenedByUser = true;
            });

            // 닫기 버튼 클릭 → 목차 닫기
            pcCloseBtn.addEventListener("click", () => {
                pcTocBox.classList.remove("show");
                pcTocOverlay.classList.remove("show");
                setTimeout(() => {
                pcTocBox.style.display = "none";
                }, 300);
                pcToggleBtn.style.display = "block";
                userClosedPcToc = true;
                isPcTocOpenedByUser = false;
            });

            // 배경 클릭으로 닫기
            pcTocOverlay.addEventListener("click", () => {
                pcTocBox.classList.remove("show");
                pcTocOverlay.classList.remove("show");  
                setTimeout(() => {
                pcTocBox.style.display = "none";
                }, 300);
                pcToggleBtn.style.display = "block";
                userClosedPcToc = true;
                isPcTocOpenedByUser = false;
            });

            // 스크롤 이벤트로 버튼 / 목차 제어
            window.addEventListener("scroll", () => {
                const scrollY = window.scrollY;
                const windowHeight = window.innerHeight;
                const documentHeight = document.documentElement.scrollHeight;
                const scrollBottom = scrollY + windowHeight;

                const showStart = 800;
                const showEnd = documentHeight - 500;
                const inMiddle = scrollY > showStart && scrollBottom < showEnd;

                if (!isPcTocOpenedByUser) {
                // 버튼만 노출
                pcToggleBtn.style.opacity = inMiddle ? "1" : "0";
                pcToggleBtn.style.pointerEvents = inMiddle ? "auto" : "none";
                } else {
                // 사용자가 펼친 후엔 버튼 숨김
                pcToggleBtn.style.opacity = "0";
                pcToggleBtn.style.pointerEvents = "none";
                }

                // 자동 닫힘
                if (!inMiddle && pcTocBox.classList.contains("show")) {
                pcTocBox.classList.remove("show");
                pcTocOverlay.classList.remove("show");
                setTimeout(() => {
                    pcTocBox.style.display = "none";
                }, 300);
                pcToggleBtn.style.display = "block";
                userClosedPcToc = false;
                }

                // 자동 열림
                if (
                inMiddle &&
                pcTocBox.style.display === "none" &&
                isPcTocOpenedByUser &&
                !userClosedPcToc
                ) {
                pcTocBox.style.display = "block";
                pcTocOverlay.classList.add("show");
                setTimeout(() => {
                    pcTocBox.classList.add("show");
                }, 10);
                pcToggleBtn.style.display = "none";
                }
            });
            });

    document.addEventListener("DOMContentLoaded", function () {
    // 모바일에서만 실행 (768px 이하)
    if (window.innerWidth > 768) return;

    const postBody = document.querySelector(".post-body");
    const mobileTocList = document.getElementById("mobile-toc-list");
    const mobileTocBox = document.querySelector(".mobile-toc-card");
    const mobileToggleBtn = document.getElementById("mobile-toc-toggle-btn");
    const mobileCloseBtn = document.getElementById("mobile-toc-close-btn");
    const mobileTocOverlay = document.getElementById("mobile-toc-overlay");

    let userClosedMobileToc = false;
    let isMobileTocOpenedByUser = false;

    if (!postBody || !mobileTocList) return;

    // 초기 버튼 상태 설정 (숨김)
    mobileToggleBtn.style.opacity = "0";
    mobileToggleBtn.style.pointerEvents = "none";

    // 자동 목차 생성 (h2 태그만, ID 생성 안함)
    const headers = postBody.querySelectorAll("h2");
    
    // [추가] h2 태그가 없으면 목차 기능을 활성화하지 않음
    if (headers.length === 0) return;

    headers.forEach((header, index) => {
        const li = document.createElement("li");
        const a = document.createElement("a");
        a.href = "#";
        a.textContent = (index + 1) + ". " + header.textContent;
        a.setAttribute("data-index", index);
        li.appendChild(a);
        mobileTocList.appendChild(li);
    });

    // 현재 위치에 따라 목차 항목 강조
    function updateActiveSection() {
        const liItems = mobileTocList.querySelectorAll("li");
        let currentSection = null;
        
        headers.forEach((header, index) => {
        const rect = header.getBoundingClientRect();
        if (rect.top <= 200 && rect.bottom >= 0) {
            currentSection = index;
        }
        });
        
        liItems.forEach((li, index) => {
        li.classList.remove("active");
        if (index === currentSection) {
            li.classList.add("active");
        }
        });
    }

    window.addEventListener("scroll", updateActiveSection);

    // 목차 항목 클릭 시 이동
    mobileTocList.addEventListener("click", function(event) {
        // [수정] a 태그 또는 그 내부 요소를 클릭했는지 확인 (패딩 영역 클릭 지원)
        const link = event.target.closest("a");
        
        if (link) {
        event.preventDefault();
        
        const index = parseInt(link.getAttribute("data-index"));
        const targetHeader = headers[index];
        
        if (targetHeader) {
            // 모든 active 클래스 제거
            const liItems = mobileTocList.querySelectorAll("li");
            liItems.forEach(li => li.classList.remove("active"));
            // 클릭한 항목에 active 클래스 추가
            link.parentElement.classList.add("active");

            // 목차 닫기
            mobileTocBox.classList.remove("show");
            mobileTocOverlay.classList.remove("show");
            setTimeout(() => {
            mobileTocBox.style.display = "none";
            }, 300);
            mobileToggleBtn.style.display = "block";

            // 해당 h2 태그로 스크롤
            setTimeout(() => {
            const headerOffset = 60; // 모바일 헤더 높이
            const elementPosition = targetHeader.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - headerOffset;

            window.scrollTo({
                top: offsetPosition,
                behavior: "smooth"
            });
            }, 350);
        }
        }
    });

    // 버튼 클릭 → 목차 열기
    mobileToggleBtn.addEventListener("click", () => {
        mobileTocBox.style.display = "block";
        mobileTocOverlay.classList.add("show");
        setTimeout(() => {
        mobileTocBox.classList.add("show");
        }, 10);
        mobileToggleBtn.style.display = "none";
        userClosedMobileToc = false;
        isMobileTocOpenedByUser = true;
    });

    // 닫기 버튼 클릭 → 목차 닫기
    mobileCloseBtn.addEventListener("click", () => {
        mobileTocBox.classList.remove("show");
        mobileTocOverlay.classList.remove("show");
        setTimeout(() => {
        mobileTocBox.style.display = "none";
        }, 300);
        mobileToggleBtn.style.display = "block";
        userClosedMobileToc = true;
        isMobileTocOpenedByUser = false;
    });

    // 배경 클릭으로 닫기
    mobileTocOverlay.addEventListener("click", () => {
        mobileTocBox.classList.remove("show");
        mobileTocOverlay.classList.remove("show");  
        setTimeout(() => {
        mobileTocBox.style.display = "none";
        }, 300);
        mobileToggleBtn.style.display = "block";
        userClosedMobileToc = true;
        isMobileTocOpenedByUser = false;
    });

    // 스크롤 이벤트로 버튼 / 목차 제어
    window.addEventListener("scroll", () => {
        const scrollY = window.scrollY;
        const windowHeight = window.innerHeight;
        const documentHeight = document.documentElement.scrollHeight;
        const scrollBottom = scrollY + windowHeight;

        const showStart = 500;
        const showEnd = documentHeight - 300;
        const inMiddle = scrollY > showStart && scrollBottom < showEnd;

        if (!isMobileTocOpenedByUser) {
        // 버튼만 노출
        mobileToggleBtn.style.opacity = inMiddle ? "1" : "0";
        mobileToggleBtn.style.pointerEvents = inMiddle ? "auto" : "none";
        } else {
        // 사용자가 펼친 후엔 버튼 숨김
        mobileToggleBtn.style.opacity = "0";
        mobileToggleBtn.style.pointerEvents = "none";
        }

        // 자동 닫힘
        if (!inMiddle && mobileTocBox.classList.contains("show")) {
        mobileTocBox.classList.remove("show");
        mobileTocOverlay.classList.remove("show");
        setTimeout(() => {
            mobileTocBox.style.display = "none";
        }, 300);
        mobileToggleBtn.style.display = "block";
        userClosedMobileToc = false;
        }

        // 자동 열림
        if (
        inMiddle &&
        mobileTocBox.style.display === "none" &&
        isMobileTocOpenedByUser &&
        !userClosedMobileToc
        ) {
        mobileTocBox.style.display = "block";
        mobileTocOverlay.classList.add("show");
        setTimeout(() => {
            mobileTocBox.classList.add("show");
        }, 10);
        mobileToggleBtn.style.display = "none";
        }
    });
    });

body.script:
document.addEventListener("DOMContentLoaded", function () {
    setTimeout(function () {
        // 매번 팝업이 나타나도록 설정 (localStorage 제거)
        document.getElementById("popupOverlay").style.display = "flex";
    }, 1500); // 1.5초 후 실행
});
function closePopup() {
    document.getElementById("popupOverlay").style.display = "none";
    // 일정 시간 후 다시 팝업이 뜨도록 설정 (10분 후 다시 보이게)
    setTimeout(function () {
        document.getElementById("popupOverlay").style.display = "flex";
    }, 600000); // 10분 후 다시 표시 (600,000ms = 10분)
}
